  function renderAccountActions() {
    if (isAccessPreviewing()) {
      return `
        <div class="user-pill preview-pill">Previewing ${escapeHtml(state.user.name)} / ${escapeHtml(state.user.role)}</div>
        <button class="secondary-btn preview-exit-btn" type="button" data-action="exit-preview">Exit preview</button>
      `;
    }
    return `
      ${
        canAdmin()
          ? `<button class="ghost-btn admin-membership-btn ${state.view === "Membership" ? "active" : ""}" type="button" data-view="Membership">Membership Model</button>`
          : ""
      }
      <div class="user-pill">${escapeHtml(state.user.name)} / ${escapeHtml(state.user.role)}</div>
      <button class="ghost-btn" type="button" data-action="reset">Reset demo</button>
      <button class="secondary-btn" type="button" data-action="logout">Logout</button>
    `;
  }

  function renderPreviewBanner() {
    if (!isAccessPreviewing()) return "";
    return `
      <section class="preview-banner" aria-label="Access preview mode">
        <div>
          <span>Access preview</span>
          <strong>${escapeHtml(state.previewAdmin.name)} is viewing ${escapeHtml(state.user.name)}'s workspace.</strong>
        </div>
        <p>Navigation, edit rights, and enabled rooms are shown through this user's access profile. Exit preview to return to admin control.</p>
        <button class="mini-btn primary-mini" type="button" data-action="exit-preview">Exit preview</button>
      </section>
    `;
  }

  function renderControlAreaCards(stats) {
    const records = companyRecords();
    const tendering = records.filter((record) => record.type === "Tender" || record.type === "EOI");
    const projects = records.filter((record) => record.type === "Project");
    const cards = [
      {
        view: "Tenders",
        label: "Tendering",
        eyebrow: "EOI and tender control",
        records: tendering.length,
        open: stats.activeTenders,
        note: "Active tendering items",
        value: sumAmounts(tendering),
      },
      {
        view: "Projects",
        label: "Projects",
        eyebrow: "Ongoing project control",
        records: projects.length,
        open: stats.ongoingProjects,
        note: "Ongoing project items",
        value: sumAmounts(projects),
      },
    ];
    return `
      <div class="insight-focus-grid control-focus-grid" aria-label="Tender control room areas">
        ${cards
          .map(
            (card) => `
              <button class="insight-focus-card ${state.view === card.view ? "active" : ""}" type="button" data-view="${escapeHtml(card.view)}">
                <span>${escapeHtml(card.eyebrow)}</span>
                <strong>${escapeHtml(card.label)}</strong>
                <small>${card.records} records / ${card.open} active / ${escapeHtml(formatCompactMoney(card.value))}</small>
                <em>${escapeHtml(card.note)}</em>
              </button>
            `,
          )
          .join("")}
      </div>
    `;
  }

  function isClosedRecord(record) {
    return ["Awarded", "Completed", "Cancelled", "Regret"].includes(record.status);
  }

  function parseRecordDate(value) {
    if (!value) return null;
    const date = new Date(`${value}T00:00:00`);
    return Number.isNaN(date.getTime()) ? null : date;
  }

  function sumAmounts(records) {
    return records.reduce((total, record) => total + (Number(record.valueAmount) || 0), 0);
  }

  function highValueThreshold(records) {
    const values = records
      .map((record) => Number(record.valueAmount) || 0)
      .filter((value) => value > 0)
      .sort((a, b) => b - a);
    if (!values.length) return Number.POSITIVE_INFINITY;
    return values[Math.min(values.length - 1, Math.max(0, Math.floor(values.length * 0.25)))];
  }

  function formatCompactMoney(value) {
    const currency = state.data.company.currency || "AED";
    const amount = Number(value) || 0;
    const abs = Math.abs(amount);
    if (abs >= 1000000000) return `${currency} ${(amount / 1000000000).toFixed(1)}B`;
    if (abs >= 1000000) return `${currency} ${(amount / 1000000).toFixed(1)}M`;
    if (abs >= 1000) return `${currency} ${Math.round(amount / 1000)}K`;
    return `${currency} ${Math.round(amount).toLocaleString("en-US")}`;
  }

  function topBreakdown(records, field, limit = 5, fallback = "Unassigned") {
    const counts = new Map();
    records.forEach((record) => {
      const label = String(record[field] || fallback).trim() || fallback;
      counts.set(label, (counts.get(label) || 0) + 1);
    });
    return Array.from(counts, ([label, value]) => ({ label, value }))
      .sort((a, b) => b.value - a.value || a.label.localeCompare(b.label))
      .slice(0, limit);
  }

  function buildStatusRows(records) {
    const extras = topBreakdown(records, "status", records.length)
      .map((row) => row.label)
      .filter((status) => !STATUS_OPTIONS.includes(status));
    return [...STATUS_OPTIONS, ...extras]
      .map((status) => ({
        label: status,
        value: records.filter((record) => record.status === status).length,
      }))
      .filter((row) => row.value > 0);
  }

  function buildDueBuckets(records) {
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    const buckets = {
      overdue: 0,
      next30: 0,
      next90: 0,
      later: 0,
      noDate: 0,
    };
    records
      .filter((record) => !isClosedRecord(record))
      .forEach((record) => {
        const date = parseRecordDate(record.endDate);
        if (!date) {
          buckets.noDate += 1;
          return;
        }
        const days = Math.ceil((date.getTime() - today.getTime()) / 86400000);
        if (days < 0) buckets.overdue += 1;
        else if (days <= 30) buckets.next30 += 1;
        else if (days <= 90) buckets.next90 += 1;
        else buckets.later += 1;
      });
    return [
      { label: "Past due", value: buckets.overdue, tone: "red" },
      { label: "Next 30 days", value: buckets.next30, tone: "amber" },
      { label: "Next 90 days", value: buckets.next90, tone: "blue" },
      { label: "Later", value: buckets.later, tone: "green" },
      { label: "No date", value: buckets.noDate, tone: "muted" },
    ];
  }

  function intakeRequests() {
    if (!Array.isArray(state.data.intakeRequests)) state.data.intakeRequests = [];
    return state.data.intakeRequests.filter((request) => request.companyId === state.user.companyId);
  }

  function intakeMissingFields(request) {
    const missing = [];
    if (!String(request.reference || "").trim()) missing.push("reference");
    if (!String(request.client || "").trim()) missing.push("client");
    if (!String(request.title || "").trim()) missing.push("title");
    if (!String(request.category || "").trim()) missing.push("category");
    if (!String(request.endDate || "").trim()) missing.push("due date");
    if (!String(request.owner || "").trim()) missing.push("owner");
    return missing;
  }

  function intakeAgeDays(request) {
    const date = new Date(request.createdAt || Date.now());
    if (Number.isNaN(date.getTime())) return 0;
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    date.setHours(0, 0, 0, 0);
    return Math.max(0, Math.round((today.getTime() - date.getTime()) / 86400000));
  }

  function intakePriority(request) {
    const amount = parseAmount(request.valueText);
    const due = parseRecordDate(request.endDate);
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    let score = 40 + intakeAgeDays(request) * 4;
    if (amount && amount >= highValueThreshold(companyRecords())) score += 25;
    if (due) {
      const days = Math.ceil((due.getTime() - today.getTime()) / 86400000);
      if (days < 0) score += 25;
      else if (days <= 14) score += 16;
      else if (days <= 30) score += 8;
    } else {
      score += 10;
    }
    score -= intakeMissingFields(request).length * 9;
    return Math.max(5, Math.min(99, Math.round(score)));
  }

  function buildIntakeModel() {
    const requests = intakeRequests().sort((a, b) => new Date(b.createdAt || 0).getTime() - new Date(a.createdAt || 0).getTime());
    const pending = requests.filter((request) => request.status === "Pending");
    const approved = requests.filter((request) => request.status === "Approved");
    const rework = requests.filter((request) => request.status === "Rework");
    const cleanPending = pending.filter((request) => !intakeMissingFields(request).length);
    const blocked = pending.filter((request) => intakeMissingFields(request).length);
    const convertedValue = approved.reduce((sum, request) => sum + (parseAmount(request.valueText) || 0), 0);
    const pendingValue = pending.reduce((sum, request) => sum + (parseAmount(request.valueText) || 0), 0);
    const oldestPending = pending.reduce((max, request) => Math.max(max, intakeAgeDays(request)), 0);
    const dueSoon = pending.filter((request) => {
      const date = parseRecordDate(request.endDate);
      if (!date) return false;
      const today = new Date();
      today.setHours(0, 0, 0, 0);
      const days = Math.ceil((date.getTime() - today.getTime()) / 86400000);
      return days <= 30;
    }).length;
    const readiness = pending.length ? Math.round((cleanPending.length / pending.length) * 100) : 100;
    const score = Math.max(0, Math.min(100, Math.round(readiness * 0.55 + Math.max(0, 100 - oldestPending * 8) * 0.25 + Math.max(0, 100 - rework.length * 15) * 0.2)));
    return {
      requests,
      pending,
      approved,
      rework,
      cleanPending,
      blocked,
      pendingValue,
      convertedValue,
      oldestPending,
      dueSoon,
      readiness,
      score,
      channelRows: topRequestBreakdown(requests, "channel", 6, "Manual request"),
      typeRows: topRequestBreakdown(requests, "type", 4, "Tender"),
      statusRows: topRequestBreakdown(requests, "status", 5, "Pending"),
      ownerRows: topRequestBreakdown(requests, "owner", 6, "Unassigned"),
      priorityRows: pending
        .map((request) => ({ request, score: intakePriority(request), missing: intakeMissingFields(request) }))
        .sort((a, b) => b.score - a.score)
        .slice(0, 8),
    };
  }

  function topRequestBreakdown(requests, field, limit = 5, fallback = "Unassigned") {
    const counts = new Map();
    requests.forEach((request) => {
      const label = String(request[field] || fallback).trim() || fallback;
      counts.set(label, (counts.get(label) || 0) + 1);
    });
    return Array.from(counts, ([label, value]) => ({ label, value }))
      .sort((a, b) => b.value - a.value || a.label.localeCompare(b.label))
      .slice(0, limit);
  }

  function ensureBidStores() {
    if (!state.data.bidDecisions || typeof state.data.bidDecisions !== "object") state.data.bidDecisions = {};
    if (!state.data.submissionReady || typeof state.data.submissionReady !== "object") state.data.submissionReady = {};
  }

  function bidDecisionFor(record) {
    ensureBidStores();
    return state.data.bidDecisions[record.id] || { decision: "Watch", by: "", at: "" };
  }

  function bidChecklistFor(record) {
    const amount = Number(record.valueAmount) || 0;
    const decision = bidDecisionFor(record).decision;
    return [
      { label: "Reference", passed: Boolean(record.reference), note: record.reference || "Missing reference" },
      { label: "Client", passed: Boolean(record.client), note: record.client || "Missing client" },
      { label: "Scope title", passed: Boolean(record.title), note: record.title || "Missing scope title" },
      { label: "Category", passed: Boolean(record.category), note: record.category || "Missing category" },
      { label: "Due date", passed: Boolean(record.endDate), note: record.endDate ? formatDate(record.endDate) : "No due date" },
      { label: "Value", passed: amount > 0, note: amount > 0 ? formatCompactMoney(amount) : "No value" },
      { label: "Owner", passed: Boolean(record.owner), note: record.owner || "No owner" },
      { label: "Source proof", passed: Boolean(record.sourceSheet || record.sourceWorkbook), note: record.sourceSheet || record.sourceWorkbook || "No source" },
      { label: "Decision", passed: decision === "Bid" || decision === "No-bid", note: decision },
    ];
  }

  function bidReadinessFor(record) {
    const checks = bidChecklistFor(record);
    return Math.round((checks.filter((item) => item.passed).length / checks.length) * 100);
  }

  function buildBidDeskModel() {
    ensureBidStores();
    const tenderRecords = sectionRecords("Tenders").filter((record) => !isClosedRecord(record));
    const rows = tenderRecords
      .map((record) => {
        const decision = bidDecisionFor(record);
        const readiness = bidReadinessFor(record);
        const date = parseRecordDate(record.endDate);
        const today = new Date();
        today.setHours(0, 0, 0, 0);
        const dueDays = date ? Math.ceil((date.getTime() - today.getTime()) / 86400000) : null;
        const ready = Boolean(state.data.submissionReady[record.id]);
        const amount = Number(record.valueAmount) || 0;
        const checklist = bidChecklistFor(record);
        const pressure =
          dueDays === null ? 18 : dueDays < 0 ? 45 : dueDays <= 7 ? 38 : dueDays <= 14 ? 28 : dueDays <= 30 ? 16 : 8;
        const priority = Math.max(1, Math.min(100, Math.round(pressure + (100 - readiness) * 0.45 + (amount > 0 ? 8 : 0))));
        return { record, decision, readiness, dueDays, ready, amount, checklist, priority };
      })
      .sort((a, b) => {
        const aDue = a.dueDays === null ? 9999 : a.dueDays;
        const bDue = b.dueDays === null ? 9999 : b.dueDays;
        return b.priority - a.priority || aDue - bDue;
      });
    const readyRows = rows.filter((row) => row.ready);
    const bidRows = rows.filter((row) => row.decision.decision === "Bid");
    const watchRows = rows.filter((row) => row.decision.decision === "Watch");
    const noBidRows = rows.filter((row) => row.decision.decision === "No-bid");
    const due14 = rows.filter((row) => row.dueDays !== null && row.dueDays <= 14).length;
    const missingRows = rows.filter((row) => row.readiness < 78);
    const totalReadiness = rows.length ? Math.round(rows.reduce((sum, row) => sum + row.readiness, 0) / rows.length) : 100;
    return {
      activeRows: rows,
      readyRows,
      bidRows,
      watchRows,
      noBidRows,
      due14,
      missingRows,
      totalReadiness,
      bidValue: sumAmounts(bidRows.map((row) => row.record)),
      readyValue: sumAmounts(readyRows.map((row) => row.record)),
      dueRows: rows.filter((row) => row.dueDays !== null && row.dueDays <= 30).slice(0, 8),
      packRows: rows.slice(0, 10),
      categoryRows: topBreakdown(rows.map((row) => row.record), "category", 6, "Uncategorized"),
      clientRows: topBreakdown(rows.map((row) => row.record), "client", 6, "No client"),
      decisionRows: [
        { label: "Bid", value: bidRows.length },
        { label: "Watch", value: watchRows.length },
        { label: "No-bid", value: noBidRows.length },
        { label: "Pack ready", value: readyRows.length },
      ],
    };
  }

  function setBidDecision(id, decision) {
    if (!canEdit()) return;
    ensureBidStores();
    const record = state.data.records.find((item) => item.id === id && item.companyId === state.user.companyId);
    if (!record || !["Bid", "Watch", "No-bid"].includes(decision)) return;
    state.data.bidDecisions[id] = {
      decision,
      by: state.user.name,
      at: new Date().toISOString(),
    };
    writeAudit("Bid decision", record.reference || record.title || "Tender", `Decision set to ${decision}.`, id, decision === "No-bid" ? "red" : decision === "Bid" ? "green" : "amber");
    persistData();
    render();
  }

  function toggleSubmissionReady(id) {
    if (!canEdit()) return;
    ensureBidStores();
    const record = state.data.records.find((item) => item.id === id && item.companyId === state.user.companyId);
    if (!record) return;
    const next = !state.data.submissionReady[id];
    if (next) state.data.submissionReady[id] = { by: state.user.name, at: new Date().toISOString() };
    else delete state.data.submissionReady[id];
    writeAudit("Submission pack", record.reference || record.title || "Tender", next ? "Marked submission pack ready." : "Cleared submission pack ready flag.", id, next ? "green" : "amber");
    persistData();
    render();
  }

  function buildImportStudioModel() {
    const records = companyRecords();
    const coverageFields = [
      ["reference", "Reference"],
      ["client", "Client"],
      ["title", "Title"],
      ["category", "Category"],
      ["status", "Status"],
      ["endDate", "Due / last date"],
      ["valueAmount", "Value"],
      ["owner", "Owner"],
      ["sourceWorkbook", "Source workbook"],
      ["sourceSheet", "Source sheet"],
    ];
    const coverageRows = coverageFields.map(([field, label]) => {
      const filled = records.filter((record) => {
        if (field === "valueAmount") return Number(record.valueAmount) > 0;
        return Boolean(String(record[field] || "").trim());
      }).length;
      return {
        field,
        label,
        filled,
        total: records.length,
        rate: records.length ? Math.round((filled / records.length) * 100) : 100,
      };
    });
    const totalSlots = coverageRows.reduce((sum, row) => sum + row.total, 0);
    const filledSlots = coverageRows.reduce((sum, row) => sum + row.filled, 0);
    const sourceRows = topBreakdown(records, "sourceWorkbook", 6, "Manual entry");
    const sheetRows = topBreakdown(records, "sourceSheet", 8, "Manual entry");
    const sourceWorkbooks = new Set(
      records
        .map((record) => String(record.sourceWorkbook || "").trim())
        .filter((label) => label && label !== "Manual entry"),
    ).size;
    const manualEntries = records.filter(
      (record) => !record.sourceWorkbook || record.sourceWorkbook === "Manual entry" || !record.sourceSheet,
    ).length;
    const duplicateMap = new Map();
    records.forEach((record) => {
      const key = normalize(record.reference);
      if (!key) return;
      if (!duplicateMap.has(key)) duplicateMap.set(key, []);
      duplicateMap.get(key).push(record);
    });
    const duplicateGroups = Array.from(duplicateMap.values())
      .filter((group) => group.length > 1)
      .map((group) => ({
        reference: group[0].reference || "No reference",
        count: group.length,
        clients: Array.from(new Set(group.map((record) => record.client).filter(Boolean))).slice(0, 3),
      }))
      .slice(0, 8);
    const missingRecords = records
      .map((record) => {
        const gaps = [];
        if (!record.reference) gaps.push("reference");
        if (!record.client) gaps.push("client");
        if (!record.title) gaps.push("title");
        if (!record.status) gaps.push("status");
        if (!record.endDate) gaps.push("date");
        if (!Number(record.valueAmount)) gaps.push("value");
        if (!record.sourceSheet) gaps.push("source");
        return { record, gaps };
      })
      .filter((item) => item.gaps.length);
    return {
      records,
      coverageRows,
      fieldCoverage: totalSlots ? Math.round((filledSlots / totalSlots) * 100) : 100,
      sourceRows,
      sheetRows,
      sourceWorkbooks,
      manualEntries,
      duplicateGroups,
      duplicateCount: duplicateGroups.reduce((sum, group) => sum + group.count, 0),
      missingRecords: missingRecords.slice(0, 8),
      missingCount: missingRecords.length,
      issueCount: duplicateGroups.length + missingRecords.length + manualEntries,
      preview: state.importPreview,
      normalization: buildImportNormalizationModel(records, state.importPreview, {
        fieldCoverage: totalSlots ? Math.round((filledSlots / totalSlots) * 100) : 100,
        duplicateGroups,
        missingRecords,
        manualEntries,
        sourceWorkbooks,
      }),
    };
  }

  function buildImportNormalizationModel(records, preview, base) {
    const sourceRows = preview && !preview.errors.length ? preview.rows.map((row) => row.record) : records;
    const issueRows = preview && !preview.errors.length ? preview.rows.filter((row) => row.issues.length) : [];
    const cleanRows = preview && !preview.errors.length ? preview.rows.filter((row) => !row.issues.length) : [];
    const total = Math.max(1, sourceRows.length);
    const operationalReady = sourceRows.filter((record) => record.reference && record.client && record.title && record.status).length;
    const commercialRows = sourceRows.filter((record) => Number(record.valueAmount) > 0 || record.valueText || record.agreementNo || record.loaReceived || record.agreementReceived).length;
    const governanceRows = sourceRows.filter((record) => record.sourceWorkbook && record.sourceSheet).length;
    const workflowRows = sourceRows.filter((record) => !record.owner || !record.endDate || ["Pending", "Submitted", "Active", "Ongoing"].includes(record.status)).length;
    const duplicateRows = base.duplicateGroups.reduce((sum, group) => sum + group.count, 0);
    const quarantineCount = preview && !preview.errors.length ? issueRows.length : base.missingRecords.length + duplicateRows + base.manualEntries;
    const commitReady = preview && !preview.errors.length ? cleanRows.length : Math.max(0, records.length - quarantineCount);
    return {
      activeMode: preview && !preview.errors.length ? "Preview batch" : "Current workspace",
      layers: IMPORT_NORMALIZATION_LAYERS.map((layer) => {
        const rate =
          layer.label === "Operational tracker"
            ? Math.round((operationalReady / total) * 100)
            : layer.label === "Commercial vault"
              ? Math.round((commercialRows / total) * 100)
              : layer.label === "Governance evidence"
                ? Math.round((governanceRows / total) * 100)
                : Math.round((workflowRows / total) * 100);
        return { ...layer, rate };
      }),
      signals: [
        ["Commit-ready", commitReady, preview ? `${cleanRows.length} clean preview rows` : "current rows passing gates", "green"],
        ["Quarantine", quarantineCount, preview ? `${issueRows.length} preview rows need cleanup` : "workspace rows need cleanup", "red"],
        ["Commercial routed", commercialRows, "rows with value or agreement facts", "amber"],
        ["Source trace", governanceRows, "rows carrying workbook and sheet", "blue"],
      ],
      steps: IMPORT_NORMALIZATION_STEPS.map(([no, title, note]) => ({ no, title, note })),
      gates: IMPORT_COMMIT_GATES.map(([label, note, tone]) => ({ label, note, tone })),
      fieldMap: [
        ["Type / status", "type, status", "records / details", "Standardize tender, EOI, project, active, awarded, completed, regret."],
        ["Identity", "reference, client, title", "records", "Create the tracker row only when core identity is present."],
        ["Dates", "startDate, endDate", "tender_details / project_details / actions", "Use due dates for calendar, reminders, and review rhythm."],
        ["Money", "valueText, currency, agreementNo", "commercial_facts", "Hide values from Tenders and Projects while feeding Insights."],
        ["Source", "sourceWorkbook, sourceSheet, sourceRow", "import_batches / audit_logs", "Keep workbook memory for audit, documents, and reports."],
        ["Owner", "owner", "users / actions", "Assign accountability or generate a missing-owner cleanup action."],
      ],
      readiness: Math.round((operationalReady / total) * 35 + (governanceRows / total) * 25 + (Math.max(0, total - quarantineCount) / total) * 25 + Math.min(1, commercialRows / total) * 15),
    };
  }

  function sampleImportCsv() {
    return [
      IMPORT_COLUMNS.join(","),
      [
        "Tender",
        "CSV-TDR-001",
        "ADNOC Gas",
        "Imported tender demo row",
        "Digital & Telecom",
        "Active",
        "2026-05-12",
        "2026-06-30",
        "AED 1250000",
        "Commercial",
        "CSV Pilot",
      ].map(csvCell).join(","),
      [
        "Project",
        "CSV-PRJ-001",
        "ADNOC HQ",
        "Imported project demo row",
        "Software",
        "Ongoing",
        "2026-05-12",
        "2026-12-31",
        "AED 450000",
        "Operations",
        "CSV Pilot",
      ].map(csvCell).join(","),
    ].join("\n");
  }

  function csvCell(value) {
    return `"${String(value ?? "").replaceAll('"', '""')}"`;
  }

  function parseDelimitedRows(text) {
    const firstLine = String(text || "").split(/\r?\n/).find((line) => line.trim()) || "";
    const delimiter = firstLine.includes("\t") && !firstLine.includes(",") ? "\t" : ",";
    const rows = [];
    let row = [];
    let cell = "";
    let inQuotes = false;
    const source = String(text || "");
    for (let index = 0; index < source.length; index += 1) {
      const char = source[index];
      const next = source[index + 1];
      if (char === '"') {
        if (inQuotes && next === '"') {
          cell += '"';
          index += 1;
        } else {
          inQuotes = !inQuotes;
        }
        continue;
      }
      if (char === delimiter && !inQuotes) {
        row.push(cell);
        cell = "";
        continue;
      }
      if ((char === "\n" || char === "\r") && !inQuotes) {
        if (char === "\r" && next === "\n") index += 1;
        row.push(cell);
        rows.push(row);
        row = [];
        cell = "";
        continue;
      }
      cell += char;
    }
    row.push(cell);
    rows.push(row);
    return rows.filter((item) => item.some((value) => String(value || "").trim()));
  }

  function normalizeImportHeader(header) {
    const key = normalize(header).replace(/[^a-z0-9]/g, "");
    const aliases = {
      type: "type",
      recordtype: "type",
      module: "type",
      reference: "reference",
      ref: "reference",
      refno: "reference",
      tenderno: "reference",
      opportunityno: "reference",
      agreementno: "agreementNo",
      contractno: "agreementNo",
      client: "client",
      customer: "client",
      account: "client",
      clientgroup: "clientGroup",
      group: "clientGroup",
      title: "title",
      description: "title",
      projectname: "title",
      tendername: "title",
      scope: "title",
      category: "category",
      discipline: "category",
      department: "department",
      status: "status",
      stage: "status",
      startdate: "startDate",
      start: "startDate",
      receiveddate: "startDate",
      enddate: "endDate",
      duedate: "endDate",
      due: "endDate",
      lastdate: "endDate",
      closingdate: "endDate",
      valuetext: "valueText",
      value: "valueText",
      amount: "valueText",
      tenderamount: "valueText",
      projectvalue: "valueText",
      currency: "currency",
      owner: "owner",
      responsible: "owner",
      assignee: "owner",
      latestactivity: "latestActivity",
      activity: "latestActivity",
      notes: "notes",
      sourcesheet: "sourceSheet",
      sheet: "sourceSheet",
      sourceworkbook: "sourceWorkbook",
      workbook: "sourceWorkbook",
      file: "sourceWorkbook",
    };
    return aliases[key] || "";
  }

  function normalizeImportType(value) {
    const key = normalize(value).replace(/[^a-z0-9]/g, "");
    if (key === "eoi" || key === "expressionofinterest") return "EOI";
    if (key === "project" || key === "projects") return "Project";
    if (key === "tender" || key === "bid" || key === "opportunity") return "Tender";
    return "Tender";
  }

  function normalizeImportStatus(value, type) {
    const raw = normalize(value);
    const exact = STATUS_OPTIONS.find((status) => normalize(status) === raw);
    if (exact) return exact;
    const key = raw.replace(/[^a-z0-9]/g, "");
    if (["won", "award", "awarded", "loa", "loareceived"].includes(key)) return "Awarded";
    if (["closed", "complete", "completed", "done", "delivered"].includes(key)) return "Completed";
    if (["cancel", "cancelled", "canceled"].includes(key)) return "Cancelled";
    if (["lost", "regret", "declined"].includes(key)) return "Regret";
    if (["submitted", "sent"].includes(key)) return "Submitted";
    if (["pending", "hold", "onhold"].includes(key)) return "Pending";
    if (["ongoing", "inprogress", "live"].includes(key)) return "Ongoing";
    return type === "Project" ? "Ongoing" : "Active";
  }

  function coerceImportDate(value) {
    const text = String(value || "").trim();
    if (!text) return "";
    if (/^\d{4}-\d{2}-\d{2}$/.test(text)) return text;
    const numeric = text.match(/^(\d{1,2})[/-](\d{1,2})[/-](\d{2,4})$/);
    if (numeric) {
      const day = Number(numeric[1]);
      const month = Number(numeric[2]);
      const year = Number(numeric[3].length === 2 ? `20${numeric[3]}` : numeric[3]);
      const date = new Date(year, month - 1, day);
      if (!Number.isNaN(date.getTime())) return formatDateForInput(date);
    }
    const parsed = new Date(text);
    return Number.isNaN(parsed.getTime()) ? "" : formatDateForInput(parsed);
  }

  function formatDateForInput(date) {
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, "0");
    const day = String(date.getDate()).padStart(2, "0");
    return `${year}-${month}-${day}`;
  }

  function buildImportPreview(text) {
    const source = String(text || "").trim();
    if (!source) {
      return {
        rows: [],
        headers: [],
        rawCount: 0,
        validCount: 0,
        issueCount: 0,
        errors: ["Paste CSV or Excel-copied rows first."],
      };
    }
    const parsedRows = parseDelimitedRows(source);
    if (parsedRows.length < 2) {
      return {
        rows: [],
        headers: parsedRows[0] || [],
        rawCount: 0,
        validCount: 0,
        issueCount: 0,
        errors: ["At least one header row and one data row are required."],
      };
    }
    const headers = parsedRows[0].map(normalizeImportHeader);
    if (!headers.some(Boolean)) {
      return {
        rows: [],
        headers: parsedRows[0],
        rawCount: parsedRows.length - 1,
        validCount: 0,
        issueCount: 0,
        errors: ["No recognized column headers found. Download the template and match its headings."],
      };
    }
    const existingReferences = new Set(companyRecords().map((record) => normalize(record.reference)).filter(Boolean));
    const importedReferences = new Set();
    const previewRows = parsedRows.slice(1).map((values, index) => {
      const raw = {};
      headers.forEach((header, columnIndex) => {
        if (header) raw[header] = String(values[columnIndex] || "").trim();
      });
      const type = normalizeImportType(raw.type);
      const status = normalizeImportStatus(raw.status, type);
      const reference = raw.reference || raw.agreementNo || "";
      const duplicateKey = normalize(reference);
      const issues = [];
      if (!reference) issues.push("Missing reference");
      if (!raw.client) issues.push("Missing client");
      if (!raw.title) issues.push("Missing title");
      if (duplicateKey && existingReferences.has(duplicateKey)) issues.push("Duplicate existing reference");
      if (duplicateKey && importedReferences.has(duplicateKey)) issues.push("Duplicate in import");
      if (duplicateKey) importedReferences.add(duplicateKey);
      const valueText = raw.valueText || "";
      const valueAmount = parseAmount(valueText);
      const record = {
        id: `PREVIEW-${index + 1}`,
        companyId: state.user.companyId,
        type,
        category: raw.category || (type === "Project" ? "Software" : "Digital & Telecom"),
        department: raw.department || raw.category || "",
        reference,
        clientGroup: raw.clientGroup || raw.client || "",
        client: raw.client || "",
        title: raw.title || "",
        status,
        startDate: coerceImportDate(raw.startDate),
        endDate: coerceImportDate(raw.endDate),
        valueText,
        valueAmount,
        currency: raw.currency || state.data.company.currency || "AED",
        owner: raw.owner || state.user.name,
        latestActivity: raw.latestActivity || "Imported through Import Studio",
        notes: raw.notes || "",
        agreementNo: raw.agreementNo || (type === "Project" ? reference : ""),
        loaReceived: "",
        agreementReceived: "",
        sourceWorkbook: raw.sourceWorkbook || "CSV Import Studio",
        sourceSheet: raw.sourceSheet || "CSV import",
        rounds: [],
      };
      return { rowNumber: index + 2, record, issues };
    }).filter((item) => item.record.reference || item.record.client || item.record.title);
    const issueCount = previewRows.reduce((sum, row) => sum + row.issues.length, 0);
    return {
      rows: previewRows,
      headers,
      rawCount: parsedRows.length - 1,
      validCount: previewRows.filter((row) => !row.issues.length).length,
      issueCount,
      errors: [],
    };
  }

  function previewImportText() {
    const input = document.getElementById("importCsvText");
    state.importText = input ? input.value : state.importText;
    state.importPreview = buildImportPreview(state.importText);
    const preview = state.importPreview;
    state.importMessage = preview.errors.length
      ? preview.errors[0]
      : `${preview.validCount} clean rows ready, ${preview.issueCount} issue${preview.issueCount === 1 ? "" : "s"} flagged.`;
    render();
  }

  function loadImportSample() {
    state.importText = sampleImportCsv();
    state.importPreview = null;
    state.importMessage = "Sample import rows loaded. Preview them before committing.";
    render();
  }

  function clearImportStudio() {
    state.importText = "";
    state.importPreview = null;
    state.importMessage = "";
    render();
  }

  function commitImportRows() {
    if (!canEdit()) return;
    const preview = state.importPreview || buildImportPreview(state.importText);
    const cleanRows = preview.rows.filter((row) => !row.issues.length);
    if (!cleanRows.length) {
      window.alert("No clean rows are ready to import.");
      return;
    }
    const stamp = Date.now();
    const records = cleanRows.map((row, index) => ({
      ...row.record,
      id: `IMP-${stamp}-${String(index + 1).padStart(3, "0")}`,
    }));
    state.data.records = [...records, ...state.data.records];
    state.selectedId = records[0].id;
    state.importText = "";
    state.importPreview = null;
    state.importMessage = `${records.length} row${records.length === 1 ? "" : "s"} imported into the live workspace.`;
    writeAudit("Import committed", `${records.length} CSV rows`, `${records.length} clean rows imported through Import Studio.`, records[0].id, "green");
    persistData();
    render();
  }

  function downloadImportTemplate() {
    const blob = new Blob([`${IMPORT_COLUMNS.join(",")}\n`], { type: "text/csv;charset=utf-8" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = "pursuitdesk-import-template.csv";
    link.click();
    URL.revokeObjectURL(link.href);
  }

  function readImportFile(file) {
    if (!file) return;
    const reader = new FileReader();
    reader.onload = () => {
      state.importText = String(reader.result || "");
      state.importPreview = null;
      state.importMessage = `${file.name} loaded. Preview it before committing.`;
      render();
    };
    reader.readAsText(file);
  }

  function ensureGovernanceStores() {
    if (!Array.isArray(state.data.audit)) state.data.audit = [];
    if (!state.data.governanceReviews || typeof state.data.governanceReviews !== "object") {
      state.data.governanceReviews = {};
    }
  }

  function writeAudit(action, target, detail, recordId = "", tone = "teal") {
    if (!state.user) return;
    ensureGovernanceStores();
    state.data.audit.unshift({
      id: `AUD-${Date.now()}-${Math.random().toString(16).slice(2, 8)}`,
      companyId: state.user.companyId,
      ts: new Date().toISOString(),
      actorId: state.user.id,
      actor: state.user.name,
      role: state.user.role,
      action,
      target,
      detail,
      recordId,
      tone,
    });
    state.data.audit = state.data.audit.slice(0, 300);
  }

  function auditFieldLabel(field) {
    const labels = {
      type: "Type",
      reference: "Reference",
      client: "Client",
      title: "Title",
      category: "Category",
      status: "Status",
      startDate: "Start date",
      endDate: "End date",
      valueText: "Value",
      owner: "Owner",
      agreementNo: "Agreement no",
      sourceSheet: "Source sheet",
    };
    return labels[field] || field;
  }

  function shortAuditValue(value) {
    const text = String(value ?? "").trim();
    if (!text) return "blank";
    return text.length > 42 ? `${text.slice(0, 39)}...` : text;
  }

  function reviewSignalsForRecord(record, floor = highValueThreshold(companyRecords())) {
    const amount = Number(record.valueAmount) || 0;
    const reasons = [];
    if (amount >= floor && amount > 0) reasons.push("High value");
    if (["Awarded", "Completed"].includes(record.status) && !record.agreementNo) reasons.push("Agreement gap");
    if (record.status === "Submitted" && (record.rounds || []).length > 0) reasons.push("Negotiated submission");
    if (!record.sourceSheet || !record.sourceWorkbook) reasons.push("Source gap");
    return reasons;
  }

  function buildDataArchitectureModel(records, users) {
    const total = Math.max(records.length, 1);
    const operationalReady = records.filter((record) =>
      Boolean(record.reference && record.client && record.title && record.status && record.category && record.owner && record.endDate),
    ).length;
    const commercialReady = records.filter((record) =>
      Boolean(Number(record.valueAmount) > 0 || record.valueText || record.agreementNo || record.loaReceived || record.agreementReceived || (record.rounds || []).length),
    ).length;
    const evidenceReady = records.filter((record) => record.sourceWorkbook && record.sourceSheet).length;
    const commercialUsers = users.filter(userHasCommercialAccess).length;
    const governanceUsers = users.filter(userHasGovernanceAccess).length;
    const operationUsers = users.filter((user) => {
      const access = normalizeUserAccess(user);
      return access.includes("tenders") || access.includes("projects");
    }).length;
    const layerCounts = {
      operations: {
        readiness: Math.round((operationalReady / total) * 100),
        count: operationalReady,
        users: operationUsers,
      },
      commercial: {
        readiness: Math.round((commercialReady / total) * 100),
        count: commercialReady,
        users: commercialUsers,
      },
      governance: {
        readiness: Math.round((evidenceReady / total) * 100),
        count: evidenceReady,
        users: governanceUsers,
      },
    };
    const guardRows = [
      {
        label: "Tracker separation",
        value: 100,
        tone: "green",
        note: "Tenders and Projects keep commercial values out of the worklist.",
      },
      {
        label: "Operational readiness",
        value: layerCounts.operations.readiness,
        tone: layerCounts.operations.readiness >= 80 ? "green" : "amber",
        note: `${records.length - operationalReady} records still need core tracker cleanup`,
      },
      {
        label: "Commercial vault coverage",
        value: layerCounts.commercial.readiness,
        tone: layerCounts.commercial.readiness >= 60 ? "teal" : "amber",
        note: `${commercialReady} records carry commercial intelligence fields`,
      },
      {
        label: "Evidence trace",
        value: layerCounts.governance.readiness,
        tone: layerCounts.governance.readiness >= 80 ? "green" : "amber",
        note: `${records.length - evidenceReady} records need source traceability`,
      },
    ];
    const layers = DATA_ARCHITECTURE_LAYERS.map((layer) => ({
      ...layer,
      ...(layerCounts[layer.key] || { readiness: 0, count: 0, users: 0 }),
    }));
    return {
      layers,
      guardRows,
      commercialUsers,
      governanceUsers,
      operationUsers,
    };
  }

  function buildCleanSchemaModel(dataArchitecture) {
    const tables = CLEAN_SCHEMA_TABLES.flatMap((group) => group.tables.map((table) => ({ ...table, group: group.group, tone: group.tone })));
    const fieldCount = tables.reduce((sum, table) => sum + table.fields.length, 0);
    const operationalTables = tables.filter((table) => ["records", "tender_details", "project_details"].includes(table.name)).length;
    const controlledTables = tables.filter((table) => ["commercial_facts", "negotiation_rounds", "subscriptions"].includes(table.name)).length;
    return {
      groups: CLEAN_SCHEMA_TABLES,
      tables,
      fieldCount,
      relationCount: CLEAN_SCHEMA_RELATIONS.length,
      guardrailCount: CLEAN_SCHEMA_GUARDRAILS.length,
      operationalTables,
      controlledTables,
      readiness: dataArchitecture.guardRows,
      relations: CLEAN_SCHEMA_RELATIONS.map(([from, to, note]) => ({ from, to, note })),
      guardrails: CLEAN_SCHEMA_GUARDRAILS.map(([label, note], index) => ({
        no: String(index + 1).padStart(2, "0"),
        label,
        note,
      })),
      migrationSteps: [
        ["01", "Create tenant core", "Move companies, users, roles, and section access out of local browser storage."],
        ["02", "Split records", "Keep common tracker fields in records and move tender/project-specific fields into detail tables."],
        ["03", "Protect commercial fields", "Move value, currency, forecast, agreement, and negotiation rounds into controlled commercial tables."],
        ["04", "Persist governance", "Store documents, imports, audit logs, review sessions, minutes, commitments, and dispatches."],
        ["05", "Connect billing", "Link subscriptions, seats, invoices, and active company status to access control."],
      ],
    };
  }

  function buildBackendArchitectureModel(cleanSchema, dataArchitecture) {
    const endpointCount = BACKEND_API_GROUPS.reduce((sum, [, routes]) => sum + routes.split(",").length, 0);
    const tableCount = cleanSchema.tables.length;
    const securityCount = BACKEND_SECURITY_CONTROLS.length;
    const rolloutCount = BACKEND_ROLLOUT_PHASES.length;
    const readiness = Math.round((dataArchitecture.operationUsers * 8 + dataArchitecture.commercialUsers * 7 + dataArchitecture.governanceUsers * 9 + tableCount * 3 + securityCount * 4) / 10);
    return {
      stack: BACKEND_STACK_LAYERS,
      apiGroups: BACKEND_API_GROUPS.map(([group, routes, note]) => ({ group, routes, note })),
      securityControls: BACKEND_SECURITY_CONTROLS.map(([label, note, tone]) => ({ label, note, tone })),
      rolloutPhases: BACKEND_ROLLOUT_PHASES.map(([no, title, note]) => ({ no, title, note })),
      signals: [
        ["Tables ready", tableCount, "from Clean Data Schema Room"],
        ["API groups", BACKEND_API_GROUPS.length, `${endpointCount} route families`],
        ["Security gates", securityCount, "before pilot data"],
        ["Rollout phases", rolloutCount, "backend build sequence"],
      ],
      readiness: Math.max(24, Math.min(72, readiness)),
      decision: "Build the first backend as a lean managed SaaS stack: app UI, Node API, managed PostgreSQL, object storage, auth, audit, and billing hooks. This keeps the first pilot fast while still protecting tenant and commercial data.",
      flow: [
        ["Browser app", "Authenticated user opens a tracker, insight, report, or membership room."],
        ["API gateway", "Route checks session, role, section access, and requested company scope."],
        ["Tenant policy", "Backend injects company_id and blocks cross-company or unapproved commercial reads."],
        ["Database and files", "PostgreSQL stores records and audit; object storage keeps evidence and exports."],
        ["Audit and reporting", "Every important movement is logged and becomes available to Governance and Reports."],
      ],
    };
  }

  function buildGovernanceModel() {
    ensureGovernanceStores();
    const records = companyRecords();
    const users = state.data.users.filter((user) => user.companyId === state.user.companyId);
    const auditRows = state.data.audit
      .filter((entry) => entry.companyId === state.user.companyId)
      .sort((a, b) => new Date(b.ts).getTime() - new Date(a.ts).getTime())
      .slice(0, 60);
    const floor = highValueThreshold(records);
    const dataArchitecture = buildDataArchitectureModel(records, users);
    const cleanSchema = buildCleanSchemaModel(dataArchitecture);
    const backendArchitecture = buildBackendArchitectureModel(cleanSchema, dataArchitecture);
    const reviewRows = records
      .map((record) => {
        const reasons = reviewSignalsForRecord(record, floor);
        const reviewed = state.data.governanceReviews[record.id] || null;
        return { record, reasons, reviewed };
      })
      .filter((item) => item.reasons.length)
      .sort((a, b) => {
        const aReviewed = a.reviewed ? 1 : 0;
        const bReviewed = b.reviewed ? 1 : 0;
        return aReviewed - bReviewed || (Number(b.record.valueAmount) || 0) - (Number(a.record.valueAmount) || 0);
      });
    const pendingReviews = reviewRows.filter((item) => !item.reviewed);
    const accessRows = users.map((user) => {
      const access = normalizeUserAccess(user);
      return {
        user,
        access,
        auditCount: auditRows.filter((entry) => entry.actorId === user.id).length,
        commercial: userHasCommercialAccess(user),
        governance: userHasGovernanceAccess(user),
      };
    });
    const recordsWithSource = records.filter((record) => record.sourceSheet && record.sourceWorkbook).length;
    const recordsWithOwner = records.filter((record) => record.owner).length;
    const reviewedCount = reviewRows.filter((item) => item.reviewed).length;
    const policyRows = [
      {
        label: "High-value review",
        value: reviewRows.length ? Math.round((reviewedCount / reviewRows.length) * 100) : 100,
        note: `${pendingReviews.length} records awaiting review`,
        tone: pendingReviews.length ? "amber" : "green",
      },
      {
        label: "Source traceability",
        value: records.length ? Math.round((recordsWithSource / records.length) * 100) : 100,
        note: `${records.length - recordsWithSource} records without full source`,
        tone: records.length - recordsWithSource ? "amber" : "green",
      },
      {
        label: "Owner coverage",
        value: records.length ? Math.round((recordsWithOwner / records.length) * 100) : 100,
        note: `${records.length - recordsWithOwner} records without owner`,
        tone: records.length - recordsWithOwner ? "red" : "green",
      },
      {
        label: "Access control",
        value: accessRows.length ? Math.round((accessRows.filter((row) => row.access.length).length / accessRows.length) * 100) : 100,
        note: `${accessRows.filter((row) => row.governance).length} users can open Governance`,
        tone: "teal",
      },
    ];
    const governanceScore = Math.round(policyRows.reduce((sum, row) => sum + row.value, 0) / Math.max(policyRows.length, 1));
    return {
      records,
      users,
      auditRows,
      reviewRows,
      pendingReviews,
      accessRows,
      policyRows,
      governanceScore,
      reviewedCount,
      sourceCoverage: records.length ? Math.round((recordsWithSource / records.length) * 100) : 100,
      ownerCoverage: records.length ? Math.round((recordsWithOwner / records.length) * 100) : 100,
      actorRows: topAuditActors(auditRows, users),
      actionRows: topAuditActions(auditRows),
      dataArchitecture,
      cleanSchema,
      backendArchitecture,
    };
  }

  function topAuditActors(auditRows, users) {
    const counts = new Map(users.map((user) => [user.name, 0]));
    auditRows.forEach((entry) => counts.set(entry.actor, (counts.get(entry.actor) || 0) + 1));
    return Array.from(counts, ([label, value]) => ({ label, value }))
      .filter((row) => row.value > 0)
      .sort((a, b) => b.value - a.value || a.label.localeCompare(b.label))
      .slice(0, 6);
  }

  function topAuditActions(auditRows) {
    const counts = new Map();
    auditRows.forEach((entry) => counts.set(entry.action, (counts.get(entry.action) || 0) + 1));
    return Array.from(counts, ([label, value]) => ({ label, value }))
      .sort((a, b) => b.value - a.value || a.label.localeCompare(b.label))
      .slice(0, 6);
  }

  function markGovernanceReviewed(id) {
    if (!canEdit()) return;
    ensureGovernanceStores();
    const record = state.data.records.find((item) => item.id === id);
    if (!record) return;
    state.data.governanceReviews[id] = {
      by: state.user.name,
      at: new Date().toISOString(),
    };
    writeAudit(
      "Governance review",
      record.reference || record.title || "Record reviewed",
      "Marked high-value or policy-sensitive record as reviewed.",
      id,
      "green",
    );
    persistData();
    render();
  }

  function insightRecords() {
    const records = companyRecords();
    const lens = state.insightLens || "Tendering";
    if (lens === "All") return records;
    if (lens === "Open") return records.filter((record) => !isClosedRecord(record));
    if (lens === "Tendering" || lens === "Tenders") {
      return records.filter((record) => record.type === "Tender" || record.type === "EOI");
    }
    if (lens === "Projects") return records.filter((record) => record.type === "Project");
    if (lens === "High value") {
      const floor = highValueThreshold(records);
      return records.filter((record) => (Number(record.valueAmount) || 0) >= floor);
    }
    return records;
  }

  function recordDueDays(record) {
    const date = parseRecordDate(record.endDate);
    if (!date) return null;
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    return Math.ceil((date.getTime() - today.getTime()) / 86400000);
  }

  function scoreRecord(record, valueFloor) {
    const amount = Number(record.valueAmount) || 0;
    const days = recordDueDays(record);
    const hasCore = [
      record.reference,
      record.client,
      record.title,
      record.category,
      record.owner,
      record.endDate,
      amount > 0 ? "value" : "",
    ].filter(Boolean).length;
    let score = 42 + hasCore * 5;
    const reasons = [];
    if (amount >= valueFloor && amount > 0) {
      score += 12;
      reasons.push("High value");
    }
    if ((record.rounds || []).length > 0) {
      score += 8;
      reasons.push("Negotiated");
    }
    if (["Submitted", "Awarded"].includes(record.status)) score += 8;
    if (record.status === "Pending") {
      score -= 5;
      reasons.push("Pending");
    }
    if (days === null) {
      score -= 12;
      reasons.push("No due date");
    } else if (days < 0) {
      score -= 20;
      reasons.push("Past due");
    } else if (days <= 14) {
      score += 3;
      reasons.push("Urgent");
    }
    if (!amount) {
      score -= 7;
      reasons.push("No value");
    }
    if (!record.owner) {
      score -= 8;
      reasons.push("No owner");
    }
    const finalScore = Math.max(5, Math.min(98, Math.round(score)));
    return {
      score: finalScore,
      recommendation: finalScore >= 72 ? "Bid focus" : finalScore >= 52 ? "Watch" : "No-bid review",
      tone: finalScore >= 72 ? "green" : finalScore >= 52 ? "amber" : "red",
      reasons: reasons.slice(0, 3),
      days,
    };
  }

  function buildDecisionRows(records) {
    const floor = highValueThreshold(companyRecords());
    return records
      .filter((record) => !isClosedRecord(record))
      .map((record) => ({ record, ...scoreRecord(record, floor) }))
      .sort((a, b) => {
        const aUrgency = a.days === null ? 9999 : a.days;
        const bUrgency = b.days === null ? 9999 : b.days;
        return a.score - b.score || aUrgency - bUrgency;
      })
      .slice(0, 6);
  }

  function buildComplianceRows(records) {
    const checks = [
      ["Reference", (record) => record.reference],
      ["Client", (record) => record.client],
      ["Tender title", (record) => record.title],
      ["Owner", (record) => record.owner],
      ["Due date", (record) => record.endDate],
      ["Value", (record) => Number(record.valueAmount) > 0],
      ["Status", (record) => record.status],
      ["Category", (record) => record.category],
    ];
    const total = Math.max(records.length, 1);
    return checks.map(([label, getter]) => {
      const ready = records.filter((record) => Boolean(getter(record))).length;
      return { label, value: Math.round((ready / total) * 100), ready };
    });
  }

  function buildRiskMatrix(records) {
    const openRecords = records.filter((record) => !isClosedRecord(record));
    const floor = highValueThreshold(companyRecords());
    const cells = [
      { label: "Urgent value", note: "High value with past or near due date", tone: "red", count: 0 },
      { label: "Clean pursuits", note: "High score and clear ownership", tone: "green", count: 0 },
      { label: "Decision gaps", note: "Missing value, date, or owner", tone: "amber", count: 0 },
      { label: "Monitor", note: "Lower pressure open records", tone: "blue", count: 0 },
    ];
    openRecords.forEach((record) => {
      const amount = Number(record.valueAmount) || 0;
      const days = recordDueDays(record);
      const scored = scoreRecord(record, floor);
      const missing = !record.endDate || !record.owner || !amount;
      if (amount >= floor && (days === null || days <= 30)) cells[0].count += 1;
      else if (scored.score >= 72 && !missing) cells[1].count += 1;
      else if (missing || scored.score < 52) cells[2].count += 1;
      else cells[3].count += 1;
    });
    return cells;
  }

  function buildPlaybookRows() {
    return [
      ["Qualify", "Go/no-go queue", "Live"],
      ["Analyze", "Risk and due-date radar", "Live"],
      ["Compare", "Offer comparison workspace", "Next"],
      ["Clarify", "Supplier/client Q&A log", "Next"],
      ["Submit", "Compliance pack checklist", "Next"],
    ];
  }

  function insightModel(records) {
    const stats = metrics();
    const lens = state.insightLens || "Tendering";
    const openRecords = records.filter((record) => !isClosedRecord(record));
    const tenderRecords = records.filter((record) => record.type === "Tender" || record.type === "EOI");
    const dueBuckets = buildDueBuckets(records);
    const overdue = dueBuckets.find((bucket) => bucket.label === "Past due").value;
    const noDate = dueBuckets.find((bucket) => bucket.label === "No date").value;
    const totalValue = sumAmounts(records);
    const openValue = sumAmounts(openRecords);
    const awardedValue = sumAmounts(records.filter((record) => ["Awarded", "Completed"].includes(record.status)));
    const negotiationRecords = records.filter((record) => (record.rounds || []).length > 0);
    const totalRounds = negotiationRecords.reduce((total, record) => total + (record.rounds || []).length, 0);
    const highValueOpen = openRecords
      .filter((record) => Number(record.valueAmount) > 0)
      .sort((a, b) => Number(b.valueAmount) - Number(a.valueAmount))
      .slice(0, 4);
    const ownerRows = topBreakdown(openRecords, "owner", 5, "Unassigned");
    const topOwner = ownerRows[0] || { label: "No owner", value: 0 };
    const openCount = Math.max(openRecords.length, 1);
    const totalCount = Math.max(records.length, 1);
    const healthScore = Math.max(
      38,
      Math.min(
        94,
        Math.round(
          78 +
            Math.min(10, stats.winProgress / 3) -
            Math.min(28, (overdue / openCount) * 34) -
            Math.min(14, (noDate / openCount) * 16) -
            Math.min(12, (stats.risk / totalCount) * 24),
        ),
      ),
    );
    const funnel =
      lens === "Projects"
        ? [
            { label: "Project universe", value: records.length },
            { label: "Ongoing delivery", value: records.filter((record) => !isClosedRecord(record)).length },
            { label: "Due-date watch", value: overdue + dueBuckets.find((bucket) => bucket.label === "Next 30 days").value },
            {
              label: "Completed or awarded",
              value: records.filter((record) => ["Awarded", "Completed"].includes(record.status)).length,
            },
            {
              label: "Cancelled or regret",
              value: records.filter((record) => ["Regret", "Cancelled"].includes(record.status)).length,
            },
          ]
        : [
            { label: "Tender and EOI universe", value: tenderRecords.length },
            {
              label: "Active attention",
              value: tenderRecords.filter((record) => !isClosedRecord(record)).length,
            },
            { label: "Submitted", value: tenderRecords.filter((record) => record.status === "Submitted").length },
            {
              label: "Awarded or completed",
              value: records.filter((record) => ["Awarded", "Completed"].includes(record.status)).length,
            },
            {
              label: "Regret or cancelled",
              value: records.filter((record) => ["Regret", "Cancelled"].includes(record.status)).length,
            },
          ];
    return {
      stats,
      lens,
      scopedRecords: records.length,
      openRecords: openRecords.length,
      healthScore,
      totalValue,
      openValue,
      awardedValue,
      recordsWithValue: records.filter((record) => Number(record.valueAmount) > 0).length,
      negotiationRecords: negotiationRecords.length,
      averageRounds: negotiationRecords.length ? (totalRounds / negotiationRecords.length).toFixed(1) : "0",
      dueBuckets,
      statusRows: buildStatusRows(records),
      categoryRows: topBreakdown(records, "category", 6, "Uncategorized"),
      clientRows: topBreakdown(records, "client", 6, "No client"),
      ownerRows,
      highValueOpen,
      topOwner,
      funnel,
      decisionRows: buildDecisionRows(records),
      complianceRows: buildComplianceRows(records),
      riskMatrix: buildRiskMatrix(records),
      playbookRows: buildPlaybookRows(),
      actionCards: [
        {
          label: "Date hygiene",
          value: `${overdue + noDate} records`,
          note: "Open items with old or missing end dates should be refreshed before the weekly review.",
        },
        {
          label: "High-value focus",
          value: highValueOpen.length ? formatCompactMoney(highValueOpen[0].valueAmount) : "AED 0",
          note: highValueOpen.length
            ? `${highValueOpen[0].client || "Top client"} is the largest active value in the current data.`
            : "No active record has a captured value yet.",
        },
        {
          label: "Workload owner",
          value: topOwner.label,
          note: `${topOwner.value} open records sit with this owner in the sample workspace.`,
        },
      ],
    };
  }

  function insightAreaSummaries() {
    const records = companyRecords();
    const dueWatchCount = (items) => {
      const due = buildDueBuckets(items);
      return due.find((bucket) => bucket.label === "Past due").value + due.find((bucket) => bucket.label === "Next 30 days").value;
    };
    const tendering = records.filter((record) => record.type === "Tender" || record.type === "EOI");
    const projects = records.filter((record) => record.type === "Project");
    return [
      {
        lens: "Tendering",
        label: "Tendering",
        eyebrow: "EOI and tender pipeline",
        records: tendering.length,
        open: tendering.filter((record) => !isClosedRecord(record)).length,
        value: sumAmounts(tendering),
        dueWatch: dueWatchCount(tendering),
      },
      {
        lens: "Projects",
        label: "Projects",
        eyebrow: "Ongoing delivery control",
        records: projects.length,
        open: projects.filter((record) => !isClosedRecord(record)).length,
        value: sumAmounts(projects),
        dueWatch: dueWatchCount(projects),
      },
    ];
  }

  function renderInsightAreaCards(activeLens) {
    return `
      <div class="insight-focus-grid" aria-label="Insight areas">
        ${insightAreaSummaries()
          .map(
            (area) => `
              <button class="insight-focus-card ${activeLens === area.lens ? "active" : ""}" type="button" data-insight-lens="${escapeHtml(area.lens)}">
                <span>${escapeHtml(area.eyebrow)}</span>
                <strong>${escapeHtml(area.label)}</strong>
                <small>${area.records} records / ${area.open} open / ${escapeHtml(formatCompactMoney(area.value))}</small>
                <em>${area.dueWatch} due-watch items</em>
              </button>
            `,
          )
          .join("")}
      </div>
    `;
  }

  function insightDueValue(model, label) {
    return model.dueBuckets.find((bucket) => bucket.label === label)?.value || 0;
  }

  function insightPosture(model) {
    const overdue = insightDueValue(model, "Past due");
    const noDate = insightDueValue(model, "No date");
    if (model.healthScore >= 76 && overdue <= 4 && noDate <= 3) {
      return { label: "Board ready", tone: "green", note: "Use this page for weekly management review and client-facing confidence." };
    }
    if (model.healthScore >= 58) {
      return { label: "Review with controls", tone: "amber", note: "Clear dates, owners, and value gaps before presenting the final position." };
    }
    return { label: "Intervention needed", tone: "red", note: "Keep the review tactical until overdue, owner, and missing-value signals are repaired." };
  }

  function renderInsightExecutiveRoom(model, isProjectLens, trackerView, areaTitle) {
    const posture = insightPosture(model);
    const overdue = insightDueValue(model, "Past due");
    const next30 = insightDueValue(model, "Next 30 days");
    const noDate = insightDueValue(model, "No date");
    const leadLine = isProjectLens
      ? "Delivery management room for project movement, owner pressure, dates, completion posture, and value exposure."
      : "Tender management room for bid movement, submission pressure, negotiation depth, owner load, and value exposure.";
    const cards = [
      {
        label: "Management posture",
        value: posture.label,
        note: posture.note,
        tone: posture.tone,
      },
      {
        label: "Review queue",
        value: `${model.decisionRows.length} items`,
        note: `${overdue} overdue / ${next30} due in 30 days / ${noDate} no-date`,
        tone: overdue ? "red" : next30 || noDate ? "amber" : "green",
      },
      {
        label: "Value exposure",
        value: formatCompactMoney(model.openValue),
        note: model.highValueOpen[0]
          ? `${model.highValueOpen[0].client || "Top account"} leads open value.`
          : "No open value captured in this lens yet.",
        tone: model.openValue ? "blue" : "amber",
      },
      {
        label: "Owner pressure",
        value: model.topOwner.label,
        note: `${model.topOwner.value} open records sit with this owner.`,
        tone: model.topOwner.value >= 8 ? "amber" : "teal",
      },
    ];
    return `
      <section class="insight-executive-room">
        <div class="insight-executive-lead">
          <div>
            <span class="panel-label">${escapeHtml(isProjectLens ? "Project management room" : "Tender management room")}</span>
            <h2>${escapeHtml(areaTitle)} command brief</h2>
            <p>${escapeHtml(leadLine)}</p>
            <div class="hero-actions">
              <button class="secondary-btn" type="button" data-action="export-insights">Export pack</button>
              <button class="ghost-btn" type="button" data-view="${escapeHtml(trackerView)}">Open tracker</button>
            </div>
          </div>
          <div class="score-ring insight-executive-score" style="--score: ${model.healthScore}">
            <div>
              <strong>${model.healthScore}</strong>
              <span>Score</span>
            </div>
          </div>
        </div>
        <div class="insight-executive-cards">
          ${cards
            .map(
              (card) => `
                <article class="insight-exec-card tone-${escapeHtml(card.tone)}">
                  <span>${escapeHtml(card.label)}</span>
                  <strong>${escapeHtml(card.value)}</strong>
                  <small>${escapeHtml(card.note)}</small>
                </article>
              `,
            )
            .join("")}
        </div>
      </section>
    `;
  }

  function renderInsightReviewQueue(rows, isProjectLens) {
    const items = rows.slice(0, 4);
    if (!items.length) return `<div class="empty-state compact">No urgent management items in this lens.</div>`;
    return `
      <div class="insight-review-list">
        ${items
          .map(({ record, recommendation, tone, reasons, days }) => {
            const dueText = days === null ? "No date" : days < 0 ? `${Math.abs(days)}d late` : `${days}d left`;
            return `
              <button class="insight-review-row tone-${escapeHtml(tone)}" type="button" data-action="select" data-id="${escapeHtml(record.id)}">
                <span>${escapeHtml(isProjectLens ? "Delivery move" : "Bid move")}</span>
                <strong>${escapeHtml(record.title || record.reference || "Untitled record")}</strong>
                <em>${escapeHtml([record.client, record.status, dueText].filter(Boolean).join(" / "))}</em>
                <small>${escapeHtml(recommendation)}${reasons.length ? ` / ${escapeHtml(reasons.join(" / "))}` : ""}</small>
              </button>
            `;
          })
          .join("")}
      </div>
    `;
  }

  function renderInsightBrief(model, isProjectLens) {
    return `
      <div class="insight-brief-list">
        ${insightBriefLines(model, isProjectLens).map((line) => `<div>${escapeHtml(line)}</div>`).join("")}
      </div>
    `;
  }

  function renderInsightControlChecklist(model, isProjectLens) {
    return `
      <div class="insight-checklist">
        ${insightChecklistRows(model, isProjectLens)
          .map(
            ([label, value, note]) => `
              <div>
                <span>${escapeHtml(label)}</span>
                <strong>${escapeHtml(value)}</strong>
                <small>${escapeHtml(note)}</small>
              </div>
            `,
          )
          .join("")}
      </div>
    `;
  }

  function insightBriefLines(model, isProjectLens) {
    const overdue = insightDueValue(model, "Past due");
    const noDate = insightDueValue(model, "No date");
    const next30 = insightDueValue(model, "Next 30 days");
    return [
      `${model.openRecords} open ${isProjectLens ? "project" : "tender"} records need management visibility.`,
      `${overdue + next30} records sit in due-watch pressure; ${noDate} have no control date.`,
      `${formatCompactMoney(model.openValue)} remains open in this lens, with ${model.recordsWithValue} valued records.`,
      `${model.topOwner.label} carries the largest owner load with ${model.topOwner.value} open records.`,
    ];
  }

  function insightChecklistRows(model, isProjectLens) {
    return [
      ["Dates", `${insightDueValue(model, "Past due") + insightDueValue(model, "No date")} issues`, "Confirm next action, submission, delivery, or review date."],
      ["Owners", model.topOwner.label, "Check workload concentration and assign support where needed."],
      ["Value", formatCompactMoney(model.openValue), "Keep commercial exposure in insights, forecast, contracts, and reports."],
      [
        isProjectLens ? "Completion" : "Bid decision",
        `${model.healthScore}/100`,
        isProjectLens ? "Confirm delivery movement and closeout posture." : "Confirm bid/no-bid, submission readiness, and negotiation next step.",
      ],
    ];
  }

  function buildInsightActionPack(model, isProjectLens, trackerView) {
    const first = model.decisionRows[0];
    const overdue = insightDueValue(model, "Past due");
    const noDate = insightDueValue(model, "No date");
    const next30 = insightDueValue(model, "Next 30 days");
    const datePressure = overdue + noDate;
    const firstDueText = first
      ? first.days === null
        ? "No control date"
        : first.days < 0
          ? `${Math.abs(first.days)} days late`
          : `${first.days} days left`
      : "No urgent item";
    return [
      {
        label: isProjectLens ? "First delivery move" : "First bid move",
        title: first ? first.record.title || first.record.reference || "Open record" : "No urgent record",
        note: first
          ? `${first.record.client || "No client"} / ${first.record.status} / ${firstDueText}`
          : "The current lens has no open management queue item.",
        meta: first ? first.recommendation : "Queue clear",
        tone: first?.tone || "green",
        actionLabel: first ? "Open record" : `Open ${trackerView}`,
        recordId: first?.record.id || "",
        view: trackerView,
      },
      {
        label: "Owner handoff",
        title: model.topOwner.label,
        note: `${model.topOwner.value} open records sit with this owner. Use the tracker for accountability and the insight room for management review.`,
        meta: model.topOwner.value >= 8 ? "Load check" : "Balanced",
        tone: model.topOwner.value >= 8 ? "amber" : "green",
        actionLabel: `Open ${trackerView}`,
        recordId: "",
        view: trackerView,
      },
      {
        label: "Control gate",
        title: datePressure ? `${datePressure} date issues` : "Dates controlled",
        note: `${overdue} overdue, ${next30} due in 30 days, and ${noDate} without a control date.`,
        meta: datePressure ? "Clean before review" : "Ready rhythm",
        tone: overdue ? "red" : noDate || next30 ? "amber" : "green",
        actionLabel: `Open ${trackerView}`,
        recordId: "",
        view: trackerView,
      },
      {
        label: "Board output",
        title: "Export review pack",
        note: "Download a text pack with score, exposure, review queue, talking points, checklist, risk map, and largest open records.",
        meta: `${model.healthScore}/100 score`,
        tone: "blue",
        actionLabel: "Export pack",
        recordId: "",
        action: "export-insights",
      },
    ];
  }

  function renderInsightActionPack(model, isProjectLens, trackerView) {
    const rows = buildInsightActionPack(model, isProjectLens, trackerView);
    return `
      <section class="insight-action-pack">
        <div class="info-head">
          <div>
            <span class="metric-label">Action pack</span>
            <h3>${escapeHtml(isProjectLens ? "Project review handoff" : "Tender review handoff")}</h3>
          </div>
          <span>${rows.length} moves</span>
        </div>
        <div class="insight-action-grid">
          ${rows
            .map((item) => {
              const attrs = item.action
                ? `data-action="${escapeHtml(item.action)}"`
                : item.recordId
                  ? `data-action="select" data-id="${escapeHtml(item.recordId)}"`
                  : `data-view="${escapeHtml(item.view)}"`;
              return `
                <article class="insight-action-card tone-${escapeHtml(item.tone)}">
                  <span>${escapeHtml(item.label)}</span>
                  <strong>${escapeHtml(item.title)}</strong>
                  <p>${escapeHtml(item.note)}</p>
                  <div>
                    <em>${escapeHtml(item.meta)}</em>
                    <button class="mini-btn" type="button" ${attrs}>${escapeHtml(item.actionLabel)}</button>
                  </div>
                </article>
              `;
            })
            .join("")}
        </div>
      </section>
    `;
  }

  function buildInsightRunSheet(model, isProjectLens, trackerView) {
    const posture = insightPosture(model);
    const first = model.decisionRows[0];
    const second = model.decisionRows[1];
    const topValue = model.highValueOpen[0];
    const overdue = insightDueValue(model, "Past due");
    const noDate = insightDueValue(model, "No date");
    const next30 = insightDueValue(model, "Next 30 days");
    const datePressure = overdue + noDate;
    const firstTitle = first?.record.title || first?.record.reference || "No urgent item";
    const secondTitle = second?.record.title || second?.record.reference || "No second item";
    return [
      {
        step: "01",
        time: "0-3 min",
        label: "Open posture",
        title: posture.label,
        note: posture.note,
        output: `${model.healthScore}/100 review score aligned`,
        tone: posture.tone,
      },
      {
        step: "02",
        time: "3-7 min",
        label: isProjectLens ? "Delivery decision" : "Bid decision",
        title: firstTitle,
        note: first ? `${first.record.client || "No client"} / ${first.recommendation}` : "No urgent record is waiting in the review queue.",
        output: first ? "Assign next action and owner" : "Confirm queue stays clear",
        tone: first?.tone || "green",
        actionLabel: first ? "Open record" : `Open ${trackerView}`,
        recordId: first?.record.id || "",
        view: trackerView,
      },
      {
        step: "03",
        time: "7-10 min",
        label: "Owner handoff",
        title: model.topOwner.label,
        note: `${model.topOwner.value} open records need movement from this ownership lane.`,
        output: model.topOwner.value >= 8 ? "Decide capacity support" : "Confirm owner rhythm",
        tone: model.topOwner.value >= 8 ? "amber" : "green",
        actionLabel: `Open ${trackerView}`,
        view: trackerView,
      },
      {
        step: "04",
        time: "10-13 min",
        label: "Date control",
        title: datePressure ? `${datePressure} control issues` : "Dates controlled",
        note: `${overdue} overdue / ${next30} next 30 days / ${noDate} no-date records.`,
        output: datePressure ? "Date cleanup owner agreed" : "No date intervention needed",
        tone: overdue ? "red" : next30 || noDate ? "amber" : "green",
        actionLabel: `Open ${trackerView}`,
        view: trackerView,
      },
      {
        step: "05",
        time: "13-16 min",
        label: "Exposure check",
        title: topValue ? `${formatCompactMoney(topValue.valueAmount)} / ${topValue.client || "Top account"}` : "No open value captured",
        note: topValue
          ? topValue.title || "Largest open record in this lens."
          : isProjectLens
            ? "Project values can stay in Project Insights once commercial capture is added."
            : "Add value only in management rooms, never in frontline tracker views.",
        output: topValue ? "Escalate, protect, or watch" : "Confirm value capture plan",
        tone: topValue ? "blue" : "amber",
        actionLabel: topValue ? "Open record" : "Export pack",
        recordId: topValue?.id || "",
        action: topValue ? "" : "export-insights",
      },
      {
        step: "06",
        time: "16-18 min",
        label: "Close review",
        title: second ? secondTitle : "Send management pack",
        note: second ? `${second.record.client || "No client"} is the next item after the first move.` : "Close with export and share the agreed review pack.",
        output: "Review pack ready for circulation",
        tone: "teal",
        actionLabel: "Export pack",
        action: "export-insights",
      },
    ];
  }

  function renderInsightRunSheet(model, isProjectLens, trackerView) {
    const rows = buildInsightRunSheet(model, isProjectLens, trackerView);
    return `
      <section class="insight-run-sheet">
        <div class="info-head">
          <div>
            <span class="metric-label">Management run sheet</span>
            <h3>${escapeHtml(isProjectLens ? "18-minute project review" : "18-minute tender review")}</h3>
          </div>
          <span>${rows.length} steps</span>
        </div>
        <div class="insight-run-list">
          ${rows
            .map((item) => {
              const attrs = item.action
                ? `data-action="${escapeHtml(item.action)}"`
                : item.recordId
                  ? `data-action="select" data-id="${escapeHtml(item.recordId)}"`
                  : item.view
                    ? `data-view="${escapeHtml(item.view)}"`
                    : "";
              return `
                <article class="insight-run-row tone-${escapeHtml(item.tone)}">
                  <div>
                    <span>${escapeHtml(item.step)}</span>
                    <em>${escapeHtml(item.time)}</em>
                  </div>
                  <section>
                    <small>${escapeHtml(item.label)}</small>
                    <strong>${escapeHtml(item.title)}</strong>
                    <p>${escapeHtml(item.note)}</p>
                  </section>
                  <footer>
                    <b>${escapeHtml(item.output)}</b>
                    ${item.actionLabel ? `<button class="mini-btn" type="button" ${attrs}>${escapeHtml(item.actionLabel)}</button>` : ""}
                  </footer>
                </article>
              `;
            })
            .join("")}
        </div>
      </section>
    `;
  }

  function buildInsightDecisionLedger(model, isProjectLens) {
    const rows = model.decisionRows.slice(0, 6).map(({ record, recommendation, tone, reasons, days, score }, index) => {
      const dueSignal = days === null ? "No control date" : days < 0 ? `${Math.abs(days)} days late` : days <= 30 ? `${days} days left` : formatDate(record.endDate);
      const decision = isProjectLens
        ? days !== null && days < 0
          ? "Recover delivery date"
          : record.status === "Completed"
            ? "Confirm closeout"
            : "Confirm delivery move"
        : recommendation === "No-bid review"
          ? "Bid/no-bid call"
          : record.status === "Submitted"
            ? "Clarification watch"
            : "Confirm bid posture";
      return {
        no: String(index + 1).padStart(2, "0"),
        decision,
        record,
        owner: record.owner || model.topOwner.label || "Unassigned",
        dueSignal,
        output: reasons.length ? reasons.join(" / ") : `${score}/100 score`,
        tone,
      };
    });
    if (rows.length) return rows;
    return [
      {
        no: "01",
        decision: "Confirm clean rhythm",
        record: null,
        owner: model.topOwner.label || "Management",
        dueSignal: "No urgent item",
        output: "Review pack can be circulated",
        tone: "green",
      },
    ];
  }

  function renderInsightDecisionLedger(model, isProjectLens) {
    const rows = buildInsightDecisionLedger(model, isProjectLens);
    return `
      <section class="insight-decision-ledger">
        <div class="info-head">
          <div>
            <span class="metric-label">Decision ledger</span>
            <h3>${escapeHtml(isProjectLens ? "Project decisions to close" : "Tender decisions to close")}</h3>
          </div>
          <span>${rows.length} items</span>
        </div>
        <div class="insight-ledger-table">
          <div class="insight-ledger-head">
            <span>No</span>
            <span>Decision</span>
            <span>Owner</span>
            <span>Due signal</span>
            <span>Output</span>
            <span>Action</span>
          </div>
          ${rows
            .map((item) => {
              const recordTitle = item.record?.title || item.record?.reference || "Management rhythm";
              return `
                <div class="insight-ledger-row tone-${escapeHtml(item.tone)}">
                  <span>${escapeHtml(item.no)}</span>
                  <strong>
                    ${escapeHtml(item.decision)}
                    <small>${escapeHtml(recordTitle)}</small>
                  </strong>
                  <em>${escapeHtml(item.owner)}</em>
                  <em>${escapeHtml(item.dueSignal)}</em>
                  <em>${escapeHtml(item.output)}</em>
                  ${
                    item.record
                      ? `<button class="mini-btn" type="button" data-action="select" data-id="${escapeHtml(item.record.id)}">Open</button>`
                      : `<button class="mini-btn" type="button" data-action="export-insights">Export</button>`
                  }
                </div>
              `;
            })
            .join("")}
        </div>
      </section>
    `;
  }

  function buildInsightCommitments(model, isProjectLens) {
    const ledgerRows = buildInsightDecisionLedger(model, isProjectLens).filter((item) => item.record);
    const rows = ledgerRows.slice(0, 4).map((item, index) => {
      const record = item.record;
      const days = recordDueDays(record);
      const isLate = days !== null && days < 0;
      const isNoDate = days === null;
      const dueLabel = isNoDate ? "Set today" : isLate ? "Today" : days <= 7 ? `${days} days` : days <= 30 ? "Next 30 days" : formatDate(record.endDate);
      const lane = isLate ? "Red follow-up" : isNoDate ? "Date assignment" : days <= 30 ? "Near-term move" : "Watch rhythm";
      return {
        no: String(index + 1).padStart(2, "0"),
        lane,
        commitment: isProjectLens
          ? item.decision === "Recover delivery date"
            ? "Publish recovery date"
            : "Confirm delivery movement"
          : item.decision === "Bid/no-bid call"
            ? "Close bid/no-bid call"
            : "Confirm bid posture",
        owner: item.owner,
        dueLabel,
        proof: isProjectLens ? "Delivery update + next date" : "Bid note + next action",
        record,
        tone: isLate ? "red" : isNoDate ? "amber" : days <= 30 ? "blue" : item.tone,
      };
    });
    if (rows.length) return rows;
    return [
      {
        no: "01",
        lane: "Clean rhythm",
        commitment: "Circulate review pack",
        owner: model.topOwner.label || "Management",
        dueLabel: "Today",
        proof: "Exported management pack",
        record: null,
        tone: "green",
      },
    ];
  }

  function renderInsightCommitmentBoard(model, isProjectLens) {
    const rows = buildInsightCommitments(model, isProjectLens);
    return `
      <section class="insight-commitment-board">
        <div class="info-head">
          <div>
            <span class="metric-label">Commitment board</span>
            <h3>${escapeHtml(isProjectLens ? "Delivery follow-through" : "Tender follow-through")}</h3>
          </div>
          <span>${rows.length} commitments</span>
        </div>
        <div class="insight-commitment-grid">
          ${rows
            .map(
              (item) => `
                <article class="insight-commitment-card tone-${escapeHtml(item.tone)}">
                  <div>
                    <span>${escapeHtml(item.no)}</span>
                    <em>${escapeHtml(item.lane)}</em>
                  </div>
                  <strong>${escapeHtml(item.commitment)}</strong>
                  <p>${escapeHtml(item.record?.title || item.record?.reference || "Management rhythm")}</p>
                  <dl>
                    <div>
                      <dt>Owner</dt>
                      <dd>${escapeHtml(item.owner)}</dd>
                    </div>
                    <div>
                      <dt>When</dt>
                      <dd>${escapeHtml(item.dueLabel)}</dd>
                    </div>
                    <div>
                      <dt>Proof</dt>
                      <dd>${escapeHtml(item.proof)}</dd>
                    </div>
                  </dl>
                  ${
                    item.record
                      ? `<button class="mini-btn" type="button" data-action="select" data-id="${escapeHtml(item.record.id)}">Open record</button>`
                      : `<button class="mini-btn" type="button" data-action="export-insights">Export pack</button>`
                  }
                </article>
              `,
            )
            .join("")}
        </div>
      </section>
    `;
  }

  function buildInsightEscalations(model, isProjectLens, trackerView) {
    const overdue = insightDueValue(model, "Past due");
    const noDate = insightDueValue(model, "No date");
    const next30 = insightDueValue(model, "Next 30 days");
    const firstRed = model.decisionRows.find((row) => row.tone === "red") || model.decisionRows[0];
    const topValue = model.highValueOpen[0];
    const ownerLoad = model.topOwner.value || 0;
    return [
      {
        label: "Executive push",
        value: overdue ? `${overdue} late` : `${next30} due-watch`,
        note: overdue
          ? `${isProjectLens ? "Delivery" : "Bid"} records are past due and need management pressure.`
          : "No late items at the top of this lens; keep near-date items moving.",
        tone: overdue ? "red" : next30 ? "amber" : "green",
        record: firstRed?.record || null,
        actionLabel: firstRed?.record ? "Open item" : `Open ${trackerView}`,
        view: trackerView,
      },
      {
        label: "Owner capacity",
        value: model.topOwner.label,
        note: `${ownerLoad} open records sit with this owner; check if support or redistribution is needed.`,
        tone: ownerLoad >= 20 ? "red" : ownerLoad >= 8 ? "amber" : "green",
        record: null,
        actionLabel: `Open ${trackerView}`,
        view: trackerView,
      },
      {
        label: "Value protection",
        value: formatCompactMoney(model.openValue),
        note: topValue
          ? `${topValue.client || "Top account"} carries the largest open exposure in this lens.`
          : "No open value is captured yet; keep commercial visibility in the management rooms.",
        tone: model.openValue ? "blue" : "amber",
        record: topValue || null,
        actionLabel: topValue ? "Open value" : "Export pack",
        action: topValue ? "" : "export-insights",
      },
      {
        label: "Control gap",
        value: noDate ? `${noDate} no-date` : "Dates clean",
        note: noDate
          ? "No-date records are invisible to time-based review until a control date is assigned."
          : "Date control is clean enough for the current review rhythm.",
        tone: noDate ? "amber" : "green",
        record: model.decisionRows.find((row) => row.days === null)?.record || null,
        actionLabel: noDate ? "Fix dates" : "Export pack",
        action: noDate ? "" : "export-insights",
        view: trackerView,
      },
    ];
  }

  function renderInsightEscalationRadar(model, isProjectLens, trackerView) {
    const rows = buildInsightEscalations(model, isProjectLens, trackerView);
    return `
      <section class="insight-escalation-radar">
        <div class="info-head">
          <div>
            <span class="metric-label">Escalation radar</span>
            <h3>${escapeHtml(isProjectLens ? "Where management should push" : "Where leadership should push")}</h3>
          </div>
          <span>${rows.length} signals</span>
        </div>
        <div class="insight-escalation-grid">
          ${rows
            .map((item) => {
              const attrs = item.action
                ? `data-action="${escapeHtml(item.action)}"`
                : item.record
                  ? `data-action="select" data-id="${escapeHtml(item.record.id)}"`
                  : `data-view="${escapeHtml(item.view || trackerView)}"`;
              return `
                <article class="insight-escalation-card tone-${escapeHtml(item.tone)}">
                  <span>${escapeHtml(item.label)}</span>
                  <strong>${escapeHtml(item.value)}</strong>
                  <p>${escapeHtml(item.note)}</p>
                  <button class="mini-btn" type="button" ${attrs}>${escapeHtml(item.actionLabel)}</button>
                </article>
              `;
            })
            .join("")}
        </div>
      </section>
    `;
  }

  function buildInsightMinutes(model, isProjectLens, trackerView) {
    const dateLabel = new Date().toLocaleDateString("en-GB", { day: "2-digit", month: "short", year: "numeric" });
    const posture = insightPosture(model);
    const ledger = buildInsightDecisionLedger(model, isProjectLens).slice(0, 3);
    const commitments = buildInsightCommitments(model, isProjectLens).slice(0, 3);
    const escalations = buildInsightEscalations(model, isProjectLens, trackerView)
      .filter((item) => item.tone !== "green")
      .slice(0, 3);
    const duePressure = insightDueValue(model, "Past due") + insightDueValue(model, "Next 30 days");
    return {
      dateLabel,
      title: `${isProjectLens ? "Project" : "Tender"} management review minutes`,
      opening: `${state.data.company.name} reviewed ${model.scopedRecords} ${isProjectLens ? "project" : "tender"} records on ${dateLabel}. The room closed at ${model.healthScore}/100 with ${model.openRecords} open records and ${duePressure} due-watch items.`,
      posture: `${posture.label}: ${posture.note}`,
      decisions: ledger.map((item) => {
        const recordTitle = item.record?.title || item.record?.reference || "Management rhythm";
        return `${item.decision} - ${recordTitle} / owner ${item.owner} / due ${item.dueSignal}.`;
      }),
      commitments: commitments.map((item) => {
        const recordTitle = item.record?.title || item.record?.reference || "Management rhythm";
        return `${item.owner} to ${item.commitment.toLowerCase()} for ${recordTitle}; proof required: ${item.proof}; timing: ${item.dueLabel}.`;
      }),
      escalations: escalations.length
        ? escalations.map((item) => `${item.label}: ${item.value}. ${item.note}`)
        : ["No executive escalation is required beyond normal review rhythm."],
      closeout: `Closeout: circulate the review pack, update tracker evidence, and reopen ${isProjectLens ? "Project Insights" : "Tenders Insights"} before the next management review.`,
    };
  }

  function renderInsightMinutesComposer(model, isProjectLens, trackerView) {
    const minutes = buildInsightMinutes(model, isProjectLens, trackerView);
    return `
      <section class="insight-minutes-composer">
        <div class="info-head">
          <div>
            <span class="metric-label">Review minutes composer</span>
            <h3>${escapeHtml(minutes.title)}</h3>
          </div>
          <button class="mini-btn" type="button" data-action="export-minutes">Export minutes</button>
        </div>
        <div class="insight-minutes-grid">
          <article class="insight-minutes-lead">
            <span>${escapeHtml(minutes.dateLabel)}</span>
            <strong>${escapeHtml(minutes.opening)}</strong>
            <p>${escapeHtml(minutes.posture)}</p>
          </article>
          <article>
            <span>Decisions recorded</span>
            ${minutes.decisions.map((line) => `<p>${escapeHtml(line)}</p>`).join("")}
          </article>
          <article>
            <span>Commitments issued</span>
            ${minutes.commitments.map((line) => `<p>${escapeHtml(line)}</p>`).join("")}
          </article>
          <article>
            <span>Escalations and closeout</span>
            ${minutes.escalations.map((line) => `<p>${escapeHtml(line)}</p>`).join("")}
            <p>${escapeHtml(minutes.closeout)}</p>
          </article>
        </div>
      </section>
    `;
  }

  function buildInsightDispatchQueue(model, isProjectLens, trackerView) {
    const commitments = buildInsightCommitments(model, isProjectLens).filter((item) => item.record).slice(0, 4);
    const escalations = buildInsightEscalations(model, isProjectLens, trackerView)
      .filter((item) => item.tone !== "green")
      .slice(0, 2);
    const rows = commitments.map((item, index) => {
      const title = item.record?.title || item.record?.reference || "Management rhythm";
      return {
        no: String(index + 1).padStart(2, "0"),
        channel: "Owner note",
        recipient: item.owner || "Management",
        subject: `${isProjectLens ? "Project" : "Tender"} follow-up: ${title}`,
        instruction: `${item.commitment}. Update the tracker, confirm the next control date, and attach ${item.proof.toLowerCase()} by ${item.dueLabel}.`,
        proof: item.proof,
        signal: item.lane,
        tone: item.tone,
        record: item.record,
      };
    });
    escalations.forEach((item) => {
      const title = item.record?.title || item.label;
      rows.push({
        no: String(rows.length + 1).padStart(2, "0"),
        channel: "Management push",
        recipient: item.record?.owner || model.topOwner.label || "Management",
        subject: `${item.label}: ${title}`,
        instruction: `${item.note} Confirm the owner, action path, and next review evidence before the next management check-in.`,
        proof: item.label === "Value protection" ? "Commercial note in Insights" : "Updated control signal",
        signal: item.value,
        tone: item.tone,
        record: item.record,
      });
    });
    if (rows.length) return rows.slice(0, 5);
    return [
      {
        no: "01",
        channel: "Review closeout",
        recipient: model.topOwner.label || "Management",
        subject: `${isProjectLens ? "Project" : "Tender"} review closeout`,
        instruction: "Circulate the review pack, confirm no open escalation needs leadership intervention, and keep the next review date visible.",
        proof: "Exported review pack",
        signal: "Clean rhythm",
        tone: "green",
        record: null,
      },
    ];
  }

  function renderInsightDispatchCenter(model, isProjectLens, trackerView) {
    const rows = buildInsightDispatchQueue(model, isProjectLens, trackerView);
    const trackerLabel = isProjectLens ? "project" : "tender";
    return `
      <section class="insight-dispatch-center">
        <div class="info-head">
          <div>
            <span class="metric-label">Review dispatch</span>
            <h3>${escapeHtml(isProjectLens ? "Project owner follow-up queue" : "Tender owner follow-up queue")}</h3>
          </div>
          <button class="mini-btn" type="button" data-action="export-dispatch">Export dispatch</button>
        </div>
        <div class="insight-dispatch-grid">
          <article class="insight-dispatch-brief">
            <span>After-review handoff</span>
            <strong>${rows.length} owner-ready notes</strong>
            <p>Use this queue after the review meeting to tell each owner what changed, what proof is expected, and which ${escapeHtml(trackerLabel)} record needs movement.</p>
          </article>
          ${rows
            .map((item) => {
              const attrs = item.record
                ? `data-action="select" data-id="${escapeHtml(item.record.id)}"`
                : `data-view="${escapeHtml(trackerView)}"`;
              return `
                <article class="insight-dispatch-card tone-${escapeHtml(item.tone)}">
                  <div>
                    <span>${escapeHtml(item.no)}</span>
                    <em>${escapeHtml(item.channel)}</em>
                  </div>
                  <strong>${escapeHtml(item.subject)}</strong>
                  <p>${escapeHtml(item.instruction)}</p>
                  <footer>
                    <small>To ${escapeHtml(item.recipient)}</small>
                    <small>${escapeHtml(item.signal)}</small>
                    <small>Proof: ${escapeHtml(item.proof)}</small>
                  </footer>
                  <button class="mini-btn" type="button" ${attrs}>${escapeHtml(item.record ? "Open record" : `Open ${trackerView}`)}</button>
                </article>
              `;
            })
            .join("")}
        </div>
      </section>
    `;
  }

